'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var dgemm = require( '@stdlib/blas/base/dgemm' ).ndarray;
var firstDifference = require( './first_difference.js' );


// MAIN //

/**
* Solves each test case using `dgemm` and a provided implementation, and verifies that the entire output buffers are identical and that the expected code path was taken.
*
* ## Notes
*
* -   Each test case is an object containing a problem (`p`), a boolean indicating whether the recursive path is expected (`recursive`; otherwise, delegation to `dgemm` is expected), and a description (`label`).
* -   The function `solve` is invoked with a problem and an output buffer and must return the number of invocations of the Strassen–Winograd kernel.
* -   Buffers are compared using the SameValue algorithm (i.e., `Object.is`), except for problems having `β ≠ 0` which are expected to take the recursive path, for which signed zeros may differ.
* -   Only the first three failures are reported individually.
*
* @private
* @param {Object} t - test object
* @param {Array<Object>} cases - test cases
* @param {string} msg - assertion message
* @param {Function} solve - function which solves a problem
*/
function verifyCases( t, cases, msg, solve ) {
	var failures;
	var strict;
	var calls;
	var ref;
	var out;
	var err;
	var p;
	var d;
	var i;

	failures = 0;
	for ( i = 0; i < cases.length; i++ ) {
		p = cases[ i ].p;
		ref = new Float64Array( p.C.buf );
		out = new Float64Array( p.C.buf );
		dgemm( p.transA, p.transB, p.M, p.N, p.K, p.alpha, p.A.buf, p.A.s1, p.A.s2, p.A.o, p.B.buf, p.B.s1, p.B.s2, p.B.o, p.beta, ref, p.C.s1, p.C.s2, p.C.o ); // eslint-disable-line max-len
		calls = solve( p, out );
		strict = ( p.beta === 0.0 || !cases[ i ].recursive );
		d = firstDifference( ref, out, strict );
		err = '';
		if ( d >= 0 ) {
			err = 'differs from `dgemm` at buffer index ' + d + ' (expected ' + ref[ d ] + ', actual ' + out[ d ] + ')';
		} else if ( ( calls > 0 ) !== cases[ i ].recursive ) {
			err = ( cases[ i ].recursive ) ? 'unexpectedly delegated to `dgemm`' : 'unexpectedly took the recursive path';
		}
		if ( err ) {
			failures += 1;
			if ( failures <= 3 ) {
				t.fail( cases[ i ].label + ': ' + err );
			}
		}
	}
	t.strictEqual( failures, 0, msg + ' (' + cases.length + ' cases)' );
}


// EXPORTS //

module.exports = verifyCases;
